import{_ as r,l as i,o as e,c as l,v as t,p,x as o,d as s,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"技术、规模报酬与替代","description":"","frontmatter":{"title":"技术、规模报酬与替代","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/production-technology.md","filePath":"econ/production-technology.md","lastUpdated":1789023840000}'),E={name:"econ/production-technology.md"};function c(m,a,A,u,_,S){const n=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="技术、规模报酬与替代" tabindex="-1">技术、规模报酬与替代 <a class="header-anchor" href="#技术、规模报酬与替代" aria-label="Permalink to &quot;技术、规模报酬与替代&quot;">​</a></h1><div class="epigraph"><p>厂商首先是一套可行的投入–产出组合，不是事先画好的成本曲线；规模报酬与替代都是这套可行集的几何。</p><footer>—— 据 Shephard, Cost and Production Functions, 1953；Mas-Colell, Whinston and Green 第 5 章整理</footer></div><p><a href="/econ/maxmin-eu">上一课</a>（Maxmin 期望效用）。在此之上，消费者一侧收到 Arrow 证券与状态价格。本课不重讲完全市场，也不把 \\(u\\) 或 \\(q_s\\) 再写一遍。缺口是：一般均衡与市场结构后课都需要「商品从哪来」——没有把投入变成产出的可行集，利润、成本、供给都没有定义。本课打开「微观：厂商与市场」，对象从偏好换成技术。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>消费课的菜单是预算切出来的束。厂商面对的不是预算，而是物质上能否做到。把可行计划写成生产集 \\(Y\\subset\\mathbb{R}^n\\)：负分量是投入，正分量是产出，\\(y\\in Y\\) 表示该净产出向量可实现。缺口因此不是最大化利润——价格还没进场——而是先钉 \\(Y\\) 的几何，使后课成本最小化有约束可写。</p><p>常用限制：\\(\\,0\\in Y\\)（可以歇业）；免费处置（少产、多用仍可行）；\\(Y\\) 闭。凸性意味着「平均计划仍可行」，排除不可分与递增的规模收益在平均意义上的冲突。单产出时可用生产函数 \\(q=f(z)\\)，\\(Y\\) 是满足 \\(q\\le f(z)\\) 的净产出。本课只钉这套语言；要素需求是下一课的对象。</p><h3 id="规模报酬不是利润-替代不是需求" tabindex="-1">规模报酬不是利润，替代不是需求 <a class="header-anchor" href="#规模报酬不是利润-替代不是需求" aria-label="Permalink to &quot;规模报酬不是利润，替代不是需求&quot;">​</a></h3><p>规模报酬：对 \\(\\lambda\\gt 1\\)，\\(y\\in Y\\) 是否蕴含 \\(\\lambda y\\in Y\\)。处处成立是规模报酬不变（CRS）；只对 \\(\\lambda\\in(0,1)\\) 成立是递减（DRS）；\\(\\lambda\\gt 1\\) 仍可行是递增（IRS）。它是 \\(Y\\) 的锥性质，不涉及价格，更不是「大厂更赚钱」。</p><p>要素替代是等产量面上的切：技术替代率 \\(\\mathrm{TRS}_{jk}=\\mathrm{MP}_j/\\mathrm{MP}_k\\)。替代弹性度量等产量的弯曲。二者都还没有要素价格；把 TRS 直接叫「要素需求」是偷运了下一课的成本最小化。</p><p><span class="marginnote">CRS 且单产出时 \\(f\\) 一次齐次，欧拉公式把产出分尽为要素贡献。这是会计恒等式的技术前提，不是分配正义。IRS 与凸 \\(Y\\) 不相容：后课竞争利润与存在性会碰到这道墙。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把技术当作给定对应：投入 \\(z\\) 能达到的产出集合。可微时边际产出 \\(\\mathrm{MP}_j=\\partial f/\\partial z_j\\)，递减边际产出是沿一条轴的凹性，不要与 DRS 混淆——DRS 是整束按比例放大，边际递减可以和 CRS 共存（Cobb–Douglas 即是）。</p><p>等产量 \\(\\{z:f(z)=q\\}\\) 替代约束。后课在要素价格 \\(w\\) 下沿等产量找切点；本课只保证等产量被定义、TRS 在光滑点存在。多产出时没有单一 \\(f\\)，必须回到 \\(Y\\) 与转换函数，不要强行写成一个 \\(q\\)。</p>',13)),(e(),p(h,null,{default:o(()=>[d(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20Y%5B%22%E7%94%9F%E4%BA%A7%E9%9B%86%20Y%22%5D%20--%3E%20GEO%5B%22%E9%97%AD%E3%80%81%E5%8F%AF%E6%AD%87%E4%B8%9A%E3%80%81%E5%85%8D%E8%B4%B9%E5%A4%84%E7%BD%AE%22%5D%0A%20%20GEO%20--%3E%20RS%5B%22%E8%A7%84%E6%A8%A1%E6%8A%A5%E9%85%AC%EF%BC%9AY%20%E7%9A%84%E9%94%A5%22%5D%0A%20%20GEO%20--%3E%20ISO%5B%22%E7%AD%89%E4%BA%A7%E9%87%8F%E4%B8%8E%20TRS%22%5D%0A%20%20RS%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%9C%A8%20Y%20%E4%B8%8A%E9%80%89%E6%88%90%E6%9C%AC%E6%9C%80%E5%B0%8F%E7%82%B9%22%5D%0A%20%20ISO%20--%3E%20LATER%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>规模报酬与替代弹性是正交的两刀。Cobb–Douglas 可以 CRS 同时每种投入边际递减；高替代弹性不蕴含 IRS。写生产时先问集合 \\(Y\\)，再问价格——下一课才把 \\(w\\) 贴上去。</p><p>本课不引入 \\(w\\)、\\(p\\)。技术在物理单位里陈述；货币数字是下一课才贴上去的。也不把 \\(Y\\) 写成限价簿可成交的数量——簿是量化栏，这里没有报价。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>闭与可歇业保证「什么都不干」可行，后课利润若为负可以选择零。免费处置让边界上的有效点成为分析对象：浪费投入仍可行，但最优不会选它。凸性让后课的一阶条件足够，也让成本函数对 \\(w\\) 凹——那是下一课 Shephard 的几何来源，本课只把凸留下。</p><p>IRS 的机制是：放大可行计划仍可行且「更有余」，竞争价格下利润要么为零要么无穷，供给对应炸开。故后课完全竞争的长期零利润默认 DRS 或 CRS 加固定成本，而不是随口写一个递增的 \\(f\\)。替代的机制是等产量弯曲：弯曲越弱，后课要素价格变化时条件需求越陡。本课不求这些弹性的公式，只指出它们读的是 \\(Y\\)，不是偏好。</p><p><span class="marginnote">不要把生产函数与<a href="/econ/expected-utility">伯努利 \\(u\\)</a>类比成「厂商的效用」。\\(f\\) 是可行性，不是排序；利润最大化才是下一课之后的目标。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>\\(Y\\) 此处是确定的。状态依存生产（收成随天气）要把净产出写成 \\(y_s\\)，商品空间沿用上一课的或有定义；本课序主干先在确定技术上走完成本与供给。也不处理外部性：别人的产量进入自己的 \\(Y\\)，是市场失灵课的对象。</p><p>不可分、整数机器、学习效应，都会破坏凸或闭的便利假设。后课若用可微一阶条件，默认已经站在光滑凸的这一边。</p><p>\\(Y\\) 不是会计主体，也不是融资结构：投入里的「资本」是实物服务。委托—代理、X 非效率是信息课。状态依存生产只需给 \\(Y\\) 加下标 \\(s\\)，不必另起技术哲学。也不把 \\(Y\\) 写成限价簿可成交量。</p><p>后课默认：厂商的约束是生产集 \\(Y\\)（或 \\(f\\)）；规模报酬与 TRS 已有定义，不再从「什么是企业」讲起。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>厂商课从生产集起笔，不从成本曲线起笔；价格尚未进场。</li><li>规模报酬是 \\(Y\\) 的锥性质；TRS 与替代弹性是等产量的几何。</li><li>凸、可歇业、免费处置是后课成本和利润的工作假设。</li><li>下一课在给定产出上贴要素价格，做成本最小化。</li><li>出处：Shephard, <em>Cost and Production Functions</em>, 1953；Mas-Colell, Whinston and Green 第 5 章。</li></ul>',13))])}const R=r(E,[["render",c]]);export{b as __pageData,R as default};
